// ---- Parse URL do broker: aceita mqtt://host:1883, mqtts://host:8883, host:port ----
function parseMqttUrl(u){
  if(!u) return null;
  var m = u.match(/^(mqtts?|tcp|ssl|wss?):\/\/([^:\/]+)(?::(\d+))?/);
  if(m){
    var proto = m[1].toLowerCase();
    var tls = (proto==='mqtts'||proto==='ssl'||proto==='wss');
    var host = m[2];
    var port = m[3] ? Number(m[3]) : (tls?8883:1883);
    return { protocol: proto, broker: host, port: port, usetls: tls };
  }
  // fallback: host:port
  var m2 = u.match(/^([^:]+):(\d+)/);
  if(m2) return { protocol:'mqtt', broker:m2[1], port:Number(m2[2]), usetls:false };
  return { protocol:'mqtt', broker:u, port:1883, usetls:false };
}

