// ─── Coleta recursiva de deviceIds monitoráveis (ignora atuadores/controlador/seletor) ───
function walk(o, out, parentKey){
  if(!o) return;
  if(Array.isArray(o)){ o.forEach(function(x){ walk(x,out,parentKey); }); return; }
  if(typeof o !== "object") return;
  var keys = Object.keys(o);
  var localCh = (o.channel != null) ? o.channel : null;
  for(var i=0;i<keys.length;i++){
    var k = keys[i], v = o[k];
    if(k.indexOf("act") === 0) continue;
    if(k === "controller") continue;
    if(k === "sel") continue;
    var role = parentKey || null;
    if(k === "deviceId" && v != null) out.push({id:v, role:role, ch:localCh});
    else if(k === "meterId" && v != null) out.push({id:v, role:role, ch:localCh});
    else if(k === "device" && v && deviceIds[v] != null) out.push({id:deviceIds[v], role:role, ch:localCh});
    else if(k === "meter" && v && meterIds[v] != null) out.push({id:meterIds[v], role:role, ch:localCh});
    if(v && typeof v === "object"){
      // se o filho eh um sub-bind (temp, vent, cond1...), passa esse nome como role
      var nextRole = (parentKey && k.match(/^\d+$/)) ? parentKey : k;
      walk(v, out, nextRole);
    }
  }
}
function resolveIds(it){
  var raw = []; walk(it.bind, raw, null);
  var byId = {};
  raw.forEach(function(r){
    var k = String(r.id);
    if(!byId[k]) byId[k] = { id:r.id, roles:[], channels:[] };
    if(r.role && byId[k].roles.indexOf(r.role) < 0) byId[k].roles.push(r.role);
    if(r.ch != null && byId[k].channels.indexOf(r.ch) < 0) byId[k].channels.push(r.ch);
  });
  // retorna array de ids simples (compat com resto do watchdog) + guarda meta separada
  var out = []; var meta = {};
  Object.keys(byId).forEach(function(k){ out.push(byId[k].id); meta[k] = { roles: byId[k].roles, channels: byId[k].channels }; });
  it.__idMeta = meta;
  return out;
}

// ─── Detecta itens offline usando SÓ deviceLastSeen (sem falso positivo de stores permanentes) ───
var curr = [], newlyOffline = [];
envs.forEach(function(env){
  (env.items || []).forEach(function(it){
    var ids = resolveIds(it);
    if(!ids.length) return;
    var staleIds = [], oldestStale = null, hasNeverSeen = false;
    ids.forEach(function(id){
      var last = Number(lastSeen[String(id)]) || 0;
      if(last === 0){
        if(uptimeCoversThreshold){ staleIds.push(String(id)); hasNeverSeen = true; }
      } else if((now - last) > thresholdMs){
        staleIds.push(String(id));
        if(oldestStale === null || last < oldestStale) oldestStale = last;
      }
    });
    if(!staleIds.length) return;

    var prevOne = prevMap[it.id];
    var displayName = it.name && String(it.name).trim() || TYPE_LABEL[it.type] || it.type || "Item";
    var entry = {
      itemId: it.id, name: displayName, type: it.type,
      typeLabel: TYPE_LABEL[it.type] || it.type,
      envId: env.id, envName: env.name,
      deviceId: staleIds.join(", "),
      staleCount: staleIds.length, totalIds: ids.length,
      neverSeen: hasNeverSeen,
      since: prevOne ? prevOne.since : now,
      lastSeen: oldestStale,
      lastSeenAt: (function(){ var last=0; ids.forEach(function(id){ var l=Number(lastSeen[String(id)])||0; if(l>last) last=l; }); return last; })(),
      allIds: ids.map(String),
      sniffCount: (function(){ var c=global.get("wdSniffCount")||{}; var t=0; ids.forEach(function(id){ t += Number(c[String(id)])||0; }); return t; })()
    };
    curr.push(entry);
    if(!prevOne) newlyOffline.push(entry);
  });
});

var diag = [];
envs.forEach(function(env){
  (env.items||[]).forEach(function(it){
    var _ids = resolveIds(it);
    if(!_ids.length) return;
    diag.push({
      itemId: it.id,
      name: (it.name && String(it.name).trim()) || TYPE_LABEL[it.type] || it.type,
      typeLabel: TYPE_LABEL[it.type] || it.type,
      envName: env.name,
      idsInfo: _ids.map(function(id){
        var last = Number(lastSeen[String(id)])||0;
        var _meta = (it.__idMeta && it.__idMeta[String(id)]) || {};
        return {
          id: String(id),
          last: last,
          ago: last ? Math.round((now-last)/1000) : null,
          roles: _meta.roles || [],
          channels: _meta.channels || []
        };
      })
    });
  });
});
global.set("wdDiag", diag);

global.set("offlineDevices", curr);
var uiMsg = { topic:"offlinelist", payload: curr };

// ─── Notificações (só recém-caídos) ───
var emailMsg = null, tgMsg = null;
function _minutesOfDay(hhmm){ var m=/^([01]?\d|2[0-3]):([0-5]\d)$/.exec(String(hhmm||"").trim()); if(!m) return null; return Number(m[1])*60+Number(m[2]); }
function _isInNotifyWindow(){
  if(!cfg.windowOn) return true;
  var st=_minutesOfDay(cfg.windowStart), en=_minutesOfDay(cfg.windowEnd);
  if(st==null || en==null) return true;
  var d=new Date(); var cur=d.getHours()*60+d.getMinutes();
  if(st===en) return true;
  if(st<en) return cur>=st && cur<en;
  return cur>=st || cur<en; // cruza meia-noite
}
var inWindow = _isInNotifyWindow();
var pendingBefore = !!context.get("wdPendingNotify");

var _wasAllOnline = context.get("wdAllOnline");
if(_wasAllOnline == null) _wasAllOnline = true;
var isAllOnline = (curr.length === 0);
var lastNotifyAt = Number(context.get("wdLastNotify")) || 0;
var resendMs = Math.max(0, Number(cfg.resendMinutes)||0) * 60 * 1000;

var shouldNotify = false;
var notifyReason = "";
if(curr.length > 0){
  if(_wasAllOnline){
    // transição: tudo estava online e agora tem offline → dispara imediato
    shouldNotify = true;
    notifyReason = "transicao";
  } else if(resendMs > 0 && (now - lastNotifyAt) >= resendMs){
    // já tem offline há tempo, passou o intervalo de resend → dispara resumo
    shouldNotify = true;
    notifyReason = "resend";
  }
}
context.set("wdAllOnline", isAllOnline);

// Se tem alerta pendente da janela anterior e agora entrou na janela → envia como pending
if(!shouldNotify && pendingBefore && inWindow && curr.length > 0){
  shouldNotify = true;
  notifyReason = "pendente";
}
// Se está fora da janela e ia notificar → bloqueia e marca pendente
if(shouldNotify && !inWindow){
  context.set("wdPendingNotify", true);
  shouldNotify = false;
}
// Se todos voltaram online, limpa pendente
if(isAllOnline){ context.set("wdPendingNotify", false); }

if(shouldNotify){
  var _acl = global.get("acl") || {};
  var cliPref = _acl.clientName ? "["+_acl.clientName+"] " : "";
  // Se é transição usa newlyOffline; se é resend, mostra a lista atual completa
  var listaAlerta = (notifyReason === "resend") ? curr : newlyOffline;
  var linhas = listaAlerta.map(function(o){
    var suf = "";
    if(o.staleCount > 1 && o.totalIds > 1) suf = " — " + o.staleCount + "/" + o.totalIds + " sub-produtos parados";
    if(o.neverSeen && o.lastSeen == null) suf += " (sem sinal desde o start)";
    return "• " + o.name + " (" + o.envName + ")" + suf;
  }).join("\n");
  var mins = cfg.thresholdMin || 45;
  var tituloExtra = (notifyReason === "resend") ? " · relembrete" : "";
  var corpoExtra = (notifyReason === "resend")
    ? ("Ainda h\u00e1 " + curr.length + " dispositivo(s) offline (relembrete a cada " + cfg.resendMinutes + " min):\n\n")
    : (listaAlerta.length + " dispositivo(s) sem comunicação há mais de " + mins + " min:\n\n");

  if(cfg.emailOn){
    var groups = _acl.groups || [];
    var rec = [];
    (cfg.emailGroups||[]).forEach(function(gid){
      var g = groups.filter(function(x){return x.id===gid;})[0];
      if(g && Array.isArray(g.members)) g.members.forEach(function(m){ if(m && m.indexOf("@")>0) rec.push(m); });
    });
    var seenE={}, dedup=[]; rec.forEach(function(x){ if(!seenE[x.toLowerCase()]){ seenE[x.toLowerCase()]=true; dedup.push(x); } });
    if(dedup.length){
      emailMsg = { to: dedup.join(", "),
        topic: cliPref + "\u26a0 Dispositivo(s) offline (>" + mins + " min)" + tituloExtra,
        payload: cliPref + corpoExtra + linhas };
    }
  }
  if(cfg.telegramOn){
    var _tgg = global.get("tg_groups") || [];
    var chats = (cfg.telegramGroups||[]).reduce(function(acc,gid){
      var g = _tgg.filter(function(x){return x.id===gid;})[0];
      if(g && g.chatId) acc.push(String(g.chatId).trim());
      return acc;
    }, []);
    if(chats.length){
      tgMsg = { chats: chats,
        text: cliPref + "\u26a0 " + listaAlerta.length + " dispositivo(s) offline (>" + mins + " min)" + tituloExtra + "\n" + linhas };
    }
  }
  context.set("wdLastNotify", now);
  context.set("wdPendingNotify", false);
}

node.status({
  fill: curr.length>0?"yellow":"green",
  shape:"dot",
  text: curr.length + " offline" + (newlyOffline.length?(" (+"+newlyOffline.length+" novos)"):"") + (uptimeCoversThreshold?"":" (carência)") + (isFirstTick?" · snapshot inicial":"")
});

// ─── Auto-check preventivo por slave (v178) ───
// Envia "checkslave" para QUALQUER id cuja ultima telemetria seja > autoCheckMinutes,
// independentemente de estar em offlineDevices. Ideia: verificar SAUDE preventivamente.
// - Slave visto ha 15 min ou mais -> dispara check.
// - Nao respondeu -> outro check 15 min depois.
// - Passou do thresholdMin -> vai pra offlineDevices normalmente (fluxo ja existente).
// - Continua sendo checado a cada 15 min infinitamente ate voltar a responder.
{
  var _autoMin = Math.max(1, Math.round(Number(cfg.autoCheckMinutes)||15));
  var _autoMs  = _autoMin * 60 * 1000;
  var _lastById = context.get("wdLastAutoCheckById") || {};

  // Coleta TODOS os ids monitoraveis de todos os envs/items (nao so os offline)
  var _knownIds = {};
  envs.forEach(function(env){
    (env.items||[]).forEach(function(it){
      resolveIds(it).forEach(function(id){ _knownIds[String(id)] = true; });
    });
  });
  var _allIds = Object.keys(_knownIds);

  // Filtra ids devidos: (now - max(lastSeen, lastCheck)) >= autoMs
  // Se nunca foi visto (lastSeen=0) e uptimeCoversThreshold, entra tambem — para nao
  // sair checando tudo no boot, respeitamos a carencia igual ao gate de offline.
  var _dueIds = _allIds.filter(function(sid){
    var _lastSeenAt  = Number(lastSeen[sid]) || 0;
    var _lastCheckAt = Number(_lastById[sid]) || 0;
    if(_lastSeenAt === 0){
      // nunca visto — so entra apos a carencia pos-boot
      if(!uptimeCoversThreshold) return false;
      return (now - _lastCheckAt) >= _autoMs;
    }
    var _ref = Math.max(_lastSeenAt, _lastCheckAt);
    return (now - _ref) >= _autoMs;
  });

  if(_dueIds.length){
    var _delay = 300;
    _dueIds.forEach(function(sid, _i){
      _lastById[sid] = now;
      setTimeout(function(){
        try {
          var _sidV = /^-?\d+(\.\d+)?$/.test(sid) ? Number(sid) : sid;
          node.send([null, null, null, {topic:"checkslave", payload:{slave:{id:_sidV}, auto:true, ts: Date.now()}}]);
        } catch(e){}
      }, _i * _delay);
    });

    // Limpa entradas de ids que nao existem mais na config (produto foi removido)
    Object.keys(_lastById).forEach(function(k){ if(!_knownIds[k]) delete _lastById[k]; });
    context.set("wdLastAutoCheckById", _lastById);

    // Auditoria
    try {
      var _log = global.get("aclog") || [];
      _log.push({
        ts: now, who: "watchdog", action: "auto-check preventivo",
        detail: _dueIds.length + "/" + _allIds.length + " id(s) — " + _dueIds.slice(0,10).join(",") + (_dueIds.length>10?"…":"")
      });
      if(_log.length > 500) _log = _log.slice(-500);
      global.set("aclog", _log);
    } catch(e){}
  } else {
    // Nenhum devido agora — apenas limpa entradas obsoletas (produto removido)
    var _changed = false;
    Object.keys(_lastById).forEach(function(k){ if(!_knownIds[k]){ delete _lastById[k]; _changed = true; } });
    if(_changed) context.set("wdLastAutoCheckById", _lastById);
  }
}

return [[uiMsg, {topic:"wdDiag", payload:diag}], emailMsg, tgMsg, null];

var p = msg.payload || {};
function _clockOk(s){ return typeof s==="string" && /^([01]?\d|2[0-3]):[0-5]\d$/.test(s.trim()); }
var next = {
  enabled: p.enabled!==false,
  thresholdMin: Math.max(1, Math.min(24*60, Math.round(Number(p.thresholdMin)||45))),
  resendMinutes: Math.max(0, Math.min(24*60, Math.round(Number(p.resendMinutes)||0))),
  autoCheckMinutes: Math.max(1, Math.min(24*60, Math.round(Number(p.autoCheckMinutes)||15))),
  resetAfterMinutes: Math.max(1, Math.min(24*60, Math.round(Number(p.resetAfterMinutes)||10))),
  windowOn: !!p.windowOn,
  windowStart: _clockOk(p.windowStart) ? String(p.windowStart).trim() : "08:00",
  windowEnd:   _clockOk(p.windowEnd)   ? String(p.windowEnd).trim()   : "22:00",
  emailOn: !!p.emailOn,
  telegramOn: !!p.telegramOn,
  emailGroups: Array.isArray(p.emailGroups) ? p.emailGroups : [],
  telegramGroups: Array.isArray(p.telegramGroups) ? p.telegramGroups : []
};
global.set("offlineCfg", next);
msg.params = ["offlinecfg", JSON.stringify(next)];
node.status({fill:"blue",shape:"dot",text:"config salva "+(next.windowOn?("["+next.windowStart+"-"+next.windowEnd+"]"):"")});
return msg;

// v180 — Marca deviceLastSeen[msg.payload.id] para QUALQUER msg vinda do Emitter.
// Formato canonico: msg.payload.id. Sem filtro de tipo, sem varredura recursiva.

if(!msg || !msg.payload || msg.payload.id == null) return null;
var key = String(msg.payload.id).trim();
if(!key) return null;

var now = Date.now();
var _ls  = global.get('deviceLastSeen') || {};
var _cnt = global.get('wdSniffCount')  || {};
_ls[key]  = now;
_cnt[key] = (_cnt[key]||0) + 1;
global.set('deviceLastSeen', _ls);
global.set('wdSniffCount', _cnt);

if(global.get('wdDebug')){ node.warn("carimbou id="+key+" total="+_cnt[key]); }

// Recuperacao imediata: se algum item na lista offline tem esse id nos allIds e agora
// TODOS os ids do item estao frescos, tira o item da lista.
var offList = global.get('offlineDevices') || [];
if(!offList.length) return null;

var thresholdMs = Math.max(1, Number((global.get('offlineCfg')||{}).thresholdMin)||45) * 60 * 1000;
var changed = false;
var kept = offList.filter(function(o){
  if(!o.allIds || o.allIds.indexOf(key) < 0) return true;
  var anyStale = o.allIds.some(function(iid){
    var last = Number(_ls[String(iid)]) || 0;
    if(last === 0) return true;
    return (now - last) > thresholdMs;
  });
  if(!anyStale){ changed = true; return false; }
  return true;
});

if(changed){
  global.set('offlineDevices', kept);
  return { topic:'offlinelist', payload: kept };
}
return null;

// v183 — Monitor de internet via curl -> https://www.google.com/generate_204
// Output do curl: "HTTP=204 TIME=0.153 ERR=" (ou HTTP=000 quando falha)
// exec node envia 3 msgs por execucao: stdout(str), stderr(str), rc({code})
var now = Date.now();
var isRc = msg.payload && typeof msg.payload === "object" && ("code" in msg.payload);
var isText = typeof msg.payload === "string";
var buf = context.get("netBuf") || { stdout:"", stderr:"", rc:null };

if(isText){
  if(msg.payload.indexOf("HTTP=") >= 0) buf.stdout += msg.payload;
  else buf.stderr += msg.payload;
  context.set("netBuf", buf);
  return null;
}

if(isRc){
  buf.rc = Number(msg.payload.code);
  var stdout = buf.stdout || "";
  // Parse: HTTP=204 TIME=0.153 ERR=
  var mHttp = /HTTP=(\d+)/.exec(stdout);
  var mTime = /TIME=([\d.]+)/.exec(stdout);
  var mErr  = /ERR=([^\n]*)/.exec(stdout);
  var httpCode = mHttp ? Number(mHttp[1]) : 0;
  var latMs = mTime ? Math.round(Number(mTime[1]) * 1000 * 10) / 10 : null;
  var errStr = mErr ? String(mErr[1]).trim() : "";
  // OK: HTTP entre 200-399 e rc do curl == 0
  var ok = (buf.rc === 0) && (httpCode >= 200 && httpCode < 400);

  context.set("netBuf", { stdout:"", stderr:"", rc:null });

  var st = global.get("netState");
  if(!st){
    st = { current:{ status: ok?"online":"offline", start: now, samplesOk:0, samplesFail:0, latSum:0, latMax:0, latMin:1e9, lastPing: now },
           history:[], totals:{ok:0,fail:0,latSum:0}, startedAt: now };
  }
  if(ok){
    st.current.samplesOk += 1;
    if(latMs != null){
      st.current.latSum += latMs;
      if(latMs > st.current.latMax) st.current.latMax = latMs;
      if(latMs < st.current.latMin) st.current.latMin = latMs;
      st.totals.latSum += latMs;
    }
    st.totals.ok += 1;
  } else {
    st.current.samplesFail += 1;
    st.totals.fail += 1;
  }
  st.current.lastPing = now;
  st.current.lastError = ok ? null : (errStr || ("rc="+buf.rc+" http="+httpCode));

  var newStatus = ok ? "online" : "offline";
  if(newStatus !== st.current.status){
    st.current.end = now;
    st.current.durMs = now - st.current.start;
    st.history.push(st.current);
    if(st.history.length > 1000) st.history = st.history.slice(-1000);
    st.current = { status:newStatus, start:now,
      samplesOk: ok?1:0, samplesFail: ok?0:1,
      latSum: ok && latMs!=null ? latMs : 0,
      latMax: ok && latMs!=null ? latMs : 0,
      latMin: ok && latMs!=null ? latMs : 1e9,
      lastPing: now, lastError: ok ? null : (errStr || ("rc="+buf.rc+" http="+httpCode)),
      end:null, durMs:null };
  }
  global.set("netState", st);

  function _pct(n,d){ return d>0 ? Math.round(n/d*1000)/10 : null; }
  function _agg(sinceMs){
    var since = now - sinceMs; var okS=0, failS=0, latSum=0, latN=0;
    var all = st.history.concat([st.current]);
    all.forEach(function(s){
      var sStart = Math.max(s.start, since); var sEnd = s.end || now;
      if(sEnd <= since) return;
      var full = (s.end||now) - s.start || 1; var frac = (sEnd - sStart) / full;
      if(s.status === "online"){
        okS += Math.round((s.samplesOk||0) * frac);
        latSum += (s.latSum||0) * frac;
        latN += Math.round((s.samplesOk||0) * frac);
      } else { failS += Math.round((s.samplesFail||0) * frac); }
    });
    return { ok:okS, fail:failS, total:okS+failS, uptimePct:_pct(okS, okS+failS), avgLat: latN>0 ? Math.round(latSum/latN*10)/10 : null };
  }
  var summary = {
    now: { status: st.current.status, since: st.current.start, latMs: latMs, lastPing: now, lastError: st.current.lastError, httpCode: httpCode, rc: buf.rc },
    last1h: _agg(60*60*1000),
    last24h: _agg(24*60*60*1000),
    last7d: _agg(7*24*60*60*1000)
  };
  var events = st.history.slice(-100).map(function(s){
    return { status:s.status, start:s.start, end:s.end||now, durMs:(s.end||now)-s.start, samplesOk:s.samplesOk, samplesFail:s.samplesFail, lastError:s.lastError };
  });

  var _txt = ok
    ? ("online · " + (latMs!=null?latMs+"ms":"?"))
    : ("OFFLINE · " + (st.current.lastError||("rc="+buf.rc)));
  node.status({fill: ok?"green":"red", shape:"dot", text: _txt});
  // v203: inclui contador de loop-tick da central no summary (prova "central viva")
  var _tk = global.get("myioTickInfo") || {};
  summary.centralAlive = {
    lastTick: _tk.lastTs || null,
    ticksLast5Min: _tk.count5m || 0,
    stale: _tk.lastTs ? ((now - _tk.lastTs) > 60000) : true
  };
  // v203: persiste em PG (saida 2)
  var _persist = {
    params: ["netlog", JSON.stringify({
      history: st.history.slice(-500),
      current: st.current,
      totals: st.totals,
      startedAt: st.startedAt,
      lastUpdate: now
    })]
  };
  return [{ topic:"netstate", payload:{ summary: summary, events: events } }, _persist];
}
return null;

// v203: contador de "central viva" — incrementa a cada 10s
// se o Node-RED trava, esse contador para; se cai internet, este contador continua (prova separada)
var info = global.get("myioTickInfo") || { count: 0, count5m: 0, lastTs: 0, buf: [] };
info.count = (info.count||0) + 1;
info.lastTs = Date.now();
info.buf = (info.buf || []).filter(function(t){ return (info.lastTs - t) < 5*60*1000; });
info.buf.push(info.lastTs);
info.count5m = info.buf.length;
global.set("myioTickInfo", info);
node.status({fill:"green", shape:"dot", text: "tick #" + info.count + " · 5min=" + info.count5m});
return null;
